test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});

test('prices that are off by float error do not lose a cent', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Pen', price: '0.29', qty: 1 }, { name: 'Ink', price: '0.57', qty: 1 }]),
    ['Pen: 0.29', 'Ink: 0.57', 'Total: 0.86'],
  );
});

test('refund lines print as a proper negative amount', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]),
    ['Refund: -0.50', 'Total: -0.50'],
  );
});

test('percent discount rounds to nearest cent', () => {
  // 84 cents * 10% = 8.4 -> 8 cents off
  assert.deepStrictEqual(
    invoice([{ name: 'A', price: '0.29', qty: 1 }, { name: 'B', price: '0.55', qty: 1 }], 10),
    ['A: 0.29', 'B: 0.55', 'Discount: -0.08', 'Total: 0.76'],
  );
});

